function rubric(c){return c.rubric.map(r=>`<div class="rubric-item"><span>${esc(r.criterion)}</span><b>${r.points} คะแนน</b></div>`).join('')}
function coverImg(k,load,cls){const key=k==='course'?'course':'c0'+k,c=window.DT_IMG&&window.DT_IMG.covers[key];if(!c)return '';return `<img class="${cls}" src="${window.DT_IMG.cover(key)}" data-local="${esc(c.local)}" width="${c.w}" height="${c.h}" alt="${esc(c.title)} · ${esc(c.scene)}" loading="${load}" ${load==='eager'?'fetchpriority="high" ':''}decoding="async" referrerpolicy="no-referrer" onerror="DT_IMG.fail(this)">`}
function figure(panel){const f=window.DT_IMG&&window.DT_IMG.fig(panel.id);if(f)return `<figure class="lesson-fig" data-fig="${esc(panel.id)}"><img src="${f.url}" data-local="${esc(f.local)}" width="${f.w}" height="${f.h}" alt="${esc(f.brief)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="DT_IMG.fail(this)"><figcaption>${esc(f.caption)}</figcaption></figure>`;return ''}
// หน้าเรียนรู้แบ่งเป็นหน้าย่อยของแต่ละหัวข้อ: เปิดดูแล้วนับว่าผ่าน ยกเว้นห้องจำลองและเช็กความเข้าใจที่ต้องลงมือทำก่อน
const LP=[['goal','🎯','เป้าหมาย'],['idea','💡','เข้าใจหลัก'],['example','🧩','ตัวอย่าง'],['sim','🔬','ห้องจำลอง'],['mistake','⚠️','ระวังพลาด'],['check','✍️','เช็กความเข้าใจ']],LP_ACT=new Set(['sim','check']);
function simKeys(mid){return window.DTSims?Object.keys(window.DTSims.defs).filter(k=>k.split('#')[0]===mid):[]}
function lpages(mid){return LP.filter(p=>p[0]!=='sim'||simKeys(mid).length)}
function pagesOf(mid){const p=me().pages||(me().pages={});return p[mid]||(p[mid]=[])}
function pageDone(mid,k){if(k==='sim'){const d=new Set(window.DTSims?window.DTSims.done():[]);return simKeys(mid).every(x=>d.has(x))}return pagesOf(mid).includes(k)}
function modPages(mid){const ps=lpages(mid);return [ps.filter(p=>pageDone(mid,p[0])).length,ps.length]}
function markPage(mid,k){const a=pagesOf(mid);if(k!=='sim'&&!a.includes(k))a.push(k);if(lpages(mid).every(p=>pageDone(mid,p[0]))&&!me().read.includes(mid)){me().read.push(mid);notify('เรียนหัวข้อนี้ครบทุกหน้าแล้ว เก่งมาก!')}save()}
function lpNav(c,mid,k){const ps=lpages(mid),[d,t]=modPages(mid),m=c.modules.find(x=>x.id===mid),mi=c.modules.indexOf(m);return `<div class="lp-prog"><b>หัวข้อ ${mi+1} · ${esc(m.title)}</b><span>เรียนแล้ว ${d}/${t} หน้า</span><i style="--p:${Math.round(d/t*100)}%"></i></div><div class="lp-steps">${ps.map(([pk,ic,tt],i)=>{const ok=pageDone(mid,pk);return `<a href="#chapter/${c.number}/learn/${mid}/${pk}" data-k="${pk}" class="${pk===k?'current':''}${ok?' done':''}" ${pk===k?'aria-current="page"':''}><b>${ok?'✓':i+1}</b><span>${ic} ${tt}</span>${LP_ACT.has(pk)&&!ok?'<em>ลงมือทำ</em>':''}</a>`}).join('')}</div>`}
function lpRefresh(c,mid,k){const n=$('#lp-nav');if(n)n.innerHTML=lpNav(c,mid,k);const ch=$('.mod-chips');if(ch)ch.outerHTML=modChips(c,mid)}
function modChips(c,cur){return `<nav class="mod-chips subtabs" aria-label="หัวข้อในบทนี้"><span class="mod-chips-h">หัวข้อในบทนี้</span>${c.modules.map((m,i)=>{const [d,t]=modPages(m.id),ok=me().read.includes(m.id);return `<a href="#chapter/${c.number}/learn/${m.id}" class="${m.id===cur?'current':''}${ok?' done':''}" ${m.id===cur?'aria-current="page"':''}><b>${ok?'✓':i+1}</b>${esc(m.title)}<small>${d}/${t}</small></a>`}).join('')}</nav>`}
/* ข้อความบทเรียนแบบเน้น: **คำสำคัญ** › ไฮไลต์ (วิชาที่ไม่ใช้เครื่องหมายนี้แสดงเหมือนเดิม) */
function rich(t){return esc(t).replace(/\*\*([^*]+?)\*\*/g,'<strong class="hl">$1</strong>')}
/* การ์ดแยกประเภท (l.types): สีกรอบต่างกันต่อประเภท แตะการ์ดเพื่อดูตัวอย่าง */
function lpTypes(l){const T=l.types;if(!T||!T.items||!T.items.length)return '';return `<section class="lp-types"><h3 class="lp-h">${esc(T.title)} <small>${T.items.length} ประเภท · แตะการ์ดเพื่อดูตัวอย่าง</small></h3><div class="lp-tgrid">${T.items.map((it,i)=>`<button type="button" class="lp-type k${(it.k??i)%6}" aria-expanded="false"><span class="lp-ti" aria-hidden="true">${esc(it.icon||'')}</span><b>${esc(it.name)}</b><p>${rich(it.desc)}</p>${it.ex?`<em><span>ตัวอย่าง</span>${rich(it.ex)}</em>`:''}</button>`).join('')}</div></section>`}
function say(text,who='Techno',img='techno-sword'){return `<div class="say"><img src="assets/${img}.webp" alt=""><div class="say-b"><b>${esc(who)}</b><p>${text}</p></div></div>`}
function lpBody(c,m,l,k){const fig=i=>l.imagePanels[i]?figure(l.imagePanels[i]):'',two=(main,f)=>`<div class="lp-split${f?'':' solo'}"><div>${main}</div>${f?`<div class="lp-figp">${f}</div>`:''}</div>`;
switch(k){
case 'goal':return say(rich(l.goal))+`<div class="lp-pre"><span>🧠 ก่อนเริ่ม</span><p>${rich(l.prerequisite)}</p></div><h3 class="lp-h">คำสำคัญที่ต้องรู้ <small>${l.glossary.length} คำ</small></h3><div class="lp-cards">${l.glossary.map((g,i)=>`<div class="lp-card k${i%5}"><b>${esc(g.term)}</b><p>${rich(g.meaning)}</p></div>`).join('')}</div>`;
case 'idea':return two(`<div class="lp-panels">${l.explanation.map((t,i)=>{const tg=(l.panelTags||[])[i];return `<div class="lp-panel k${tg?tg[0]%6:i%5}${tg?' tagged':''}">${tg?`<span class="lp-cat">${esc(tg[1])}</span>`:''}<span class="lp-no">${i+1}</span><p>${rich(t)}</p></div>`}).join('')}</div>`,fig(0))+lpTypes(l);
case 'example':return say('ดูตัวอย่างนี้ทีละช่อง แล้วลองคิดตามว่าทำไมถึงตอบแบบนั้น')+two(`<ol class="lp-strip">${l.workedSteps.map((t,i)=>`<li class="k${i%5}"><span class="lp-no">${i+1}</span><p>${rich(t)}</p></li>`).join('')}</ol>`,fig(1));
case 'sim':return say('ลองแตะ ลาก หรือปรับค่าในห้องจำลอง ทำภารกิจย่อยให้ครบ หน้านี้จึงจะผ่าน')+'<div class="sim-slot"></div>';
case 'mistake':return `<div class="lp-vs"><div class="lp-mx wrong"><span class="lp-tag">❌ หลายคนเข้าใจผิดว่า</span><p>${rich(l.commonMistake.wrong)}</p></div><div class="lp-vsb" aria-hidden="true">VS</div><div class="lp-mx right"><span class="lp-tag">✅ ลองคิดใหม่แบบนี้</span><p>${rich(l.commonMistake.repair)}</p></div></div>${fig(2)?`<div class="lp-figw">${fig(2)}</div>`:''}`;
case 'check':{const ans=(me().checks||{})[m.id]||'',ok=pageDone(m.id,'check'),ga=l.guidedActivities[0];return say(rich(l.selfCheck.prompt),'คำถามจาก Techno')+(ok?`<div class="lp-ans"><span class="lp-tag">คำตอบของคุณ</span><p>${esc(ans)}</p></div><div class="lp-reveal"><div class="lp-mx hint"><span class="lp-tag">💡 แนวคิด</span><p>${rich(l.selfCheck.hint)}</p></div><div class="lp-mx right"><span class="lp-tag">📘 คำอธิบาย</span><p>${rich(l.selfCheck.explanation)}</p></div></div><p class="lp-note">เทียบคำตอบของคุณกับคำอธิบาย ถ้ายังไม่ครบ แก้คำตอบได้เสมอ</p><details class="lp-edit"><summary>แก้คำตอบ</summary><textarea id="lp-ans" maxlength="1500">${esc(ans)}</textarea>${button('บันทึกคำตอบใหม่','lp-check',`data-id="${m.id}"`,'secondary')}</details>`:`<label class="lp-ansbox">พิมพ์คำตอบด้วยคำของคุณเอง (อย่างน้อย 1 ประโยค)<textarea id="lp-ans" maxlength="1500" placeholder="ฉันคิดว่า... เพราะ...">${esc(ans)}</textarea></label><div class="lp-act">${button('ส่งคำตอบ แล้วดูคำอธิบาย','lp-check',`data-id="${m.id}"`,'green')}</div>`)+(ga?`<a class="lp-lab" href="#chapter/${c.number}/practice"><span>🧪</span><b>อยากลองต่อ? ไปที่ด่านฝึก</b><small>ฝึกตอบ แล้วต่อด้วยภารกิจลงมือ ระบบตรวจให้ทันที</small></a>`:'')}
}return ''}
function learn(c,sub,page){const m=c.modules.find(x=>x.id===sub)||c.modules[0],l=D.lessons[m.id],ps=lpages(m.id),k=(ps.find(p=>p[0]===page)||ps.find(p=>!pageDone(m.id,p[0]))||ps[0])[0],pi=ps.findIndex(p=>p[0]===k),mi=c.modules.indexOf(m);
if(!LP_ACT.has(k))markPage(m.id,k);
const href=(mm,pk)=>`#chapter/${c.number}/learn/${mm.id}/${pk}`,prev=pi>0?[href(m,ps[pi-1][0]),ps[pi-1][2]]:mi>0?[href(c.modules[mi-1],'check'),'หัวข้อก่อนหน้า']:null,next=pi<ps.length-1?[href(m,ps[pi+1][0]),ps[pi+1][2]]:mi<c.modules.length-1?[href(c.modules[mi+1],'goal'),'หัวข้อถัดไป: '+c.modules[mi+1].title]:[`#chapter/${c.number}/practice`,'ไปทำด่านฝึก'];
const [ic,tt]=[ps[pi][1],ps[pi][2]];
return `<div class="study-flow">${modChips(c,m.id)}<div class="lp-nav" id="lp-nav" role="navigation" aria-label="หน้าในหัวข้อนี้">${lpNav(c,m.id,k)}</div><article class="paper lesson lp lp-${k}" id="${m.id}" data-page="${k}"><div class="lp-head"><span class="lp-burst">${ic}</span><div><small>หน้า ${pi+1} จาก ${ps.length}${LP_ACT.has(k)?' · ต้องลงมือทำ':''}</small><h2>${esc(tt)}</h2></div><span class="lp-topic">${esc(m.title)}</span></div><div class="lp-body">${lpBody(c,m,l,k)}</div></article><nav class="mod-nav lp-pager" aria-label="เปลี่ยนหน้า">${prev?`<a class="btn secondary" href="${prev[0]}">‹ ${esc(prev[1])}</a>`:'<span></span>'}<a class="btn green" href="${next[0]}">${esc(next[1])} ›</a></nav></div>`}

// The twenty lab types share persistence, but each uses its own model or editor.
function field(s,key,label,placeholder='',type='textarea'){const val=s.values[key]??'';return `<label>${label}${type==='textarea'?`<textarea data-lab-field="${key}" placeholder="${esc(placeholder)}" maxlength="4000">${esc(val)}</textarea>`:`<input data-lab-field="${key}" type="${type}" value="${esc(val)}" placeholder="${esc(placeholder)}" ${type==='number'?'min="0" step="any"':''}>`}</label>`}
function select(s,key,label,options){return `<label>${label}<select data-lab-field="${key}"><option value="">เลือก…</option>${options.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${s.values[key]===v?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`}
const sequenceDefaults={process_redesign:['นำของทั้งหมดมารวมกัน','แบ่งตามชนิดและการใช้งาน','กำหนดช่องสำหรับแต่ละหมวด','ลองหยิบแล้วคืนช่องเดิม'],dependency_timeline:['ทดสอบตามเกณฑ์','ประกอบชิ้นส่วน','กำหนดปัญหาและข้อจำกัด','วัดและร่างแบบ','เลือกวัสดุและเตรียมชิ้นส่วน','ปรับปรุงจากผลทดสอบ'],portfolio_story:['ข้อจำกัดและสิ่งที่อยากพัฒนาต่อ','ปัญหาที่พบและเกณฑ์','ผลทดสอบรุ่นแรก','แบบร่างรุ่นแรก','แบบที่ปรับและเหตุผล','ผลทดสอบรุ่นใหม่']};
function sequence(a,s){if(!s.order?.length)s.order=[...sequenceDefaults[a.interaction]];return `<p class="field-help">กดปุ่ม “ก่อน / หลัง” เพื่อจัดลำดับ ใช้ได้ทั้งเมาส์ สัมผัส และคีย์บอร์ด</p><ol class="sequence">${s.order.map((t,i)=>`<li><strong>${esc(t)}</strong><button class="move" data-action="move" data-i="${i}" data-dir="-1" aria-label="ย้าย ${esc(t)} ไปก่อน" ${i===0?'disabled':''}>▲</button><button class="move" data-action="move" data-i="${i}" data-dir="1" aria-label="ย้าย ${esc(t)} ไปหลัง" ${i===s.order.length-1?'disabled':''}>▼</button></li>`).join('')}</ol>`}
function widget(a,s){switch(a.interaction){
case 'scene_annotation':return `<p>ติ๊กเลือกของที่จะอธิบายอย่างน้อย 3 อย่าง แล้วตอบในกล่องของแต่ละอย่าง 2 เรื่อง คือ ของนั้นเป็นประเภทอะไร และช่วยแก้ปัญหาอะไรบนโต๊ะ</p>${['ถาดดินสอ','ป้ายหมวด','ก้อนหินที่ยังไม่ได้ดัดแปลง','กระดาษ','นาฬิกา'].map((n,i)=>`<div class="card mt"><label class="check-row"><input type="checkbox" data-lab-field="pick${i}" ${s.values['pick'+i]?'checked':''}><span>${n}</span></label>${select(s,'kind'+i,'จำแนกเป็น',['ชิ้นงาน','วิธีการ','สิ่งธรรมชาติ'])}${field(s,'use'+i,'หน้าที่และปัญหาที่ช่วยแก้','อธิบายจากสิ่งที่สังเกต ไม่ใช้แค่คำว่ามีประโยชน์')}</div>`).join('')}`;
case 'process_redesign':return sequence(a,s)+field(s,'categories','ถาดมี 3 ช่อง คุณจะแบ่งของ 6 ชนิดอย่างไร','บอกเกณฑ์ที่ใช้จัด และวิธีคืนของให้เป็นระเบียบ')+field(s,'test','จะตรวจได้อย่างไรว่าหาของเร็วขึ้น','ใช้ของชุดเดิม คนเดิม และวิธีจับเวลาเดิมก่อน–หลัง');
case 'cause_chain':return `<div class="field-grid three">${select(s,'cause','1. เหตุหรือข้อจำกัด',['ห้องพักมีพื้นที่น้อย','ใช้ผ้าครั้งละจำนวนมาก'])}${select(s,'change','2. ทางเลือกที่เกิดขึ้น',['เครื่องซักผ้าขนาดเล็ก','เครื่องซักผ้าขนาดใหญ่'])}${select(s,'effect','3. ผลกระทบที่ต้องคิด',['ใช้พื้นที่น้อยแต่ซักต่อรอบได้น้อย','ซักได้มากต่อรอบแต่ใช้พื้นที่มาก'])}</div><div id="model-result">${model(a,s).html}</div>`;
case 'constraint_switch':return select(s,'context','เลือกบริบทที่จะพิจารณา',['ไฟดับหนึ่งวัน มีน้ำ อ่าง และเสื้อ 5 ตัว','มีไฟฟ้า แต่ห้องมีพื้นที่จำกัด'])+select(s,'method','เลือกวิธี',['ซักมือด้วยอ่าง','ใช้เครื่องซักผ้าขนาดเล็ก','ใช้เครื่องซักผ้าขนาดใหญ่'])+field(s,'tradeoff','ข้อดี ข้อจำกัด และลำดับงาน','วิธีนี้ใช้ทรัพยากรอะไร และต้องยอมแลกเรื่องใด')+`<div id="model-result">${model(a,s).html}</div>`;
case 'system_builder':return `<p>ระบบรดน้ำอัตโนมัติ: เลือกองค์ประกอบให้ตรงหน้าที่ แล้วดูข้อมูลที่ไหลในระบบ</p><div class="system-grid">${[['input','ข้อมูลเข้า'],['process','กระบวนการ'],['output','ผลผลิต'],['feedback','ข้อมูลย้อนกลับ']].map(([k,t])=>`<div class="system-slot"><b>${t}</b>${select(s,k,'องค์ประกอบ',[['sensor','ค่าความชื้นดินที่วัดได้'],['controller','ตัวควบคุมเปรียบเทียบค่ากับเกณฑ์'],['water','น้ำที่ส่งให้พืช'],['measure','วัดความชื้นหลังรดแล้วส่งกลับ']])}</div>`).join('')}</div><div id="model-result">${model(a,s).html}</div>`;
case 'fault_injection':return select(s,'fault','สถานการณ์ขัดข้อง',['ดินชื้นแล้ว แต่เซนเซอร์ยังแจ้งว่าแห้ง','ปั๊มทำงาน แต่สายยางอุดตัน'])+select(s,'part','ส่วนที่ควรตรวจเป็นอันดับแรก',['ข้อมูลเข้าและการวัด','กระบวนการส่งน้ำ'])+field(s,'diagnose','หลักฐานและการทดสอบที่จะแยกสาเหตุ','เช่น เปรียบเทียบค่าที่วัดกับสภาพดิน โดยยังไม่เปลี่ยนทุกส่วนพร้อมกัน')+`<div id="model-result">${model(a,s).html}</div>`;
case 'material_tradeoff':return `<p>ข้อมูลสมมติเพื่อฝึกตัดสินใจ: A ราคา 20 บาท รองรับ 0.3 กก./ชิ้น · B ราคา 50 บาท รองรับ 1 กก./ชิ้น ต้องเลือกแผ่นฐานหนึ่งชิ้นที่รับ 0.5 กก. และงบรวมไม่เกิน 60 บาท ไม่ถือว่าซ้อน A แล้วรับน้ำหนักเพิ่มได้</p><div class="field-grid">${field(s,'a','จำนวน A','0','number')}${field(s,'b','จำนวน B','0','number')}</div><div id="model-result">${model(a,s).html}</div>`;
case 'tool_plan':return `<div class="field-grid">${select(s,'operation','งานที่จะทำ',['วัดขนาดกระดาษแข็ง','ตัดกระดาษแข็ง','ยึดชิ้นกระดาษแข็ง'])}${select(s,'tool','เครื่องมือหรืออุปกรณ์',['ไม้บรรทัด','กรรไกรที่เหมาะกับวัสดุ','เทปกาว'])}</div>${field(s,'safe','ขั้นตอนและการใช้เครื่องมืออย่างปลอดภัย','ระบุจุดวัด จุดตัด วิธีรองรับชิ้นงาน และเมื่อใดควรขอครูช่วย')}<div id="model-result">${model(a,s).html}</div>`;
case 'circuit_sim':return `<p>แบบจำลองวงจรไฟแสดงสถานะ ใช้แหล่งจ่าย 3V กับหลอดไฟที่เหมาะสม ปุ่มสวิตช์ใช้เปิด–ปิดวงจร ไม่ใช่แบบต่อไฟบ้าน</p><div class="circuit-board ${s.values.connected&&s.values.switch?'closed':''}"><div class="battery">แบตเตอรี่<br>3V</div><button class="switch" data-action="switch">สวิตช์ ${s.values.switch?'ปิดวงจร':'เปิดวงจร'}</button><div class="lamp ${s.values.connected&&s.values.switch?'on':''}" aria-label="หลอดไฟ ${s.values.connected&&s.values.switch?'ติด':'ดับ'}">${s.values.connected&&s.values.switch?'ติด':'ดับ'}</div></div><label class="check-row"><input type="checkbox" data-lab-field="connected" ${s.values.connected?'checked':''}><span>เชื่อมสายไฟครบจากแบตเตอรี่ ผ่านสวิตช์และหลอด กลับสู่แบตเตอรี่</span></label><div id="model-result">${model(a,s).html}</div>`;
case 'mechanism_sim':return `<p>แบบจำลองล้อและเพลา หมุนร่วมกันหนึ่งรอบเท่ากัน เปลี่ยนรัศมีเพื่อดูระยะรอบวง แบบจำลองยังไม่รวมแรงเสียดทานและน้ำหนักจริง</p><label>รัศมีล้อ (ซม.)<input type="range" min="2" max="10" value="${s.values.radius||4}" data-lab-field="radius"></label><label>รัศมีเพลา (ซม.)<input type="range" min="1" max="2" value="${s.values.axle||1}" data-lab-field="axle"></label><div id="model-result">${model(a,s).html}</div>`;
case 'problem_statement':return field(s,'user','ใครพบปัญหา และพบตอนไหน','ผู้ใช้หนึ่งคนกับสถานการณ์ที่สังเกต')+field(s,'observation','สิ่งที่สังเกตได้จริง','แยกสิ่งที่เห็นกับสิ่งที่เดา')+field(s,'need','ความต้องการและเกณฑ์ความสำเร็จ','ระบุหน้าที่ที่ต้องการ ไม่รีบเลือกว่าจะซื้ออะไร');
case 'ideation_compare':return `<div class="field-grid">${field(s,'idea1','แนวทางที่ 1','อธิบายหลักการและข้อจำกัด')}${field(s,'idea2','แนวทางที่ 2','ให้ต่างที่วิธีแก้ ไม่ใช่เปลี่ยนสี')}</div>`+field(s,'criteria','ใช้เกณฑ์ใดเปรียบเทียบและเลือก','พื้นที่ 20×15 ซม. งบ 60 บาท และหยิบของได้สะดวก');
case 'dimension_sketch':return `<p>ร่างแบบมุมมองด้านบนในกรอบนี้ หรืออธิบายตำแหน่งและขนาดด้วยข้อความด้านล่าง กริดเป็นเพียงพื้นร่าง ไม่ใช่สเกลจริงจนกว่าจะใส่ขนาดกำกับ</p><div class="drawing-tools"><span class="tag">ปากกาสีเขียว</span>${button('ย้อนเส้นล่าสุด','undo-sketch','','secondary small')}${button('ล้างแบบร่าง','clear-sketch','','secondary small')}</div><div class="sketch-wrap"><canvas id="sketch" class="sketch" aria-label="พื้นที่วาดแบบร่าง ใช้ช่องคำอธิบายทดแทนการวาดได้"></canvas></div><div class="field-grid mt">${field(s,'width','ความกว้างรวม (ซม.)','ไม่เกิน 20','number')}${field(s,'depth','ความลึกรวม (ซม.)','ไม่เกิน 15','number')}</div>${field(s,'drawingText','อธิบายแบบและขนาดแต่ละส่วน','ใส่จำนวนช่อง ตำแหน่ง ความกว้าง–ลึก และวิธีเก็บไม้บรรทัดยาว 18 ซม.')}<div id="model-result">${model(a,s).html}</div>`;
case 'dependency_timeline':return sequence(a,s)+field(s,'dependencies','งานใดต้องรอก่อน และจะเผื่อเวลาแก้ไขอย่างไร','เช่น ต้องรู้ขนาดก่อนตัดชิ้นส่วน พร้อมจุดตรวจระหว่างทำ')+`<div id="model-result">${model(a,s).html}</div>`;
case 'case_analysis':return `<div class="callout"><strong>กรณีตัวอย่างสมมติ</strong><p>ที่เก็บรุ่นแรกมีฐาน 18×12 ซม. แต่ของเล็กไหลไปปนกัน ผู้เรียนเพิ่มแผงกั้นในพื้นที่เดิมและติดป้ายหมวด ก่อนทดสอบด้วยของชุดเดิม 4 ชิ้น ยังไม่มีข้อมูลเวลาหลังปรับ</p></div>`+field(s,'evidence','หลักฐานใดบอกว่าควรแก้ปัญหาอะไร','อ้างข้อมูลจากกรณี')+field(s,'unknown','ข้อมูลใดยังไม่รู้ และจะหามาอย่างไร','อย่าเขียนว่าผ่าน 15 วินาที หากยังไม่มีผลทดสอบ');
case 'readiness_audit':return `<p>ตรวจตามความพร้อมจริง ข้อที่ยังไม่พร้อมไม่ใช่ความผิด ให้เขียนสิ่งที่ต้องเตรียมเพิ่ม</p>${['มีแบบพร้อมขนาดแต่ละส่วน','วัสดุและเครื่องมือเหมาะกับงาน','ครูอนุญาตและมีผู้ดูแลขั้นตอนที่ต้องใช้เครื่องมือ','กำหนดวิธีทดสอบและตารางบันทึกแล้ว'].map((t,i)=>`<label class="check-row"><input type="checkbox" data-lab-field="ready${i}" ${s.values['ready'+i]?'checked':''}><span>${t}</span></label>`).join('')}<div class="mt">${field(s,'pending','สิ่งที่ยังต้องเตรียมหรือขอความช่วยเหลือ','ถ้าพร้อมทุกข้อ ให้อธิบายว่าจะเริ่มขั้นใดก่อน')}</div>`;
case 'test_protocol':return select(s,'mode','ผลชุดนี้มาจากอะไร',['ยังไม่ได้ทดลอง','ทดลองชิ้นงานจริง','ทดลองแบบจำลองดิจิทัล'])+field(s,'control','เงื่อนไขที่คงเดิมทั้ง 3 รอบ','ของชุดเดิม 4 ชิ้น ตำแหน่งเริ่มเดิม คนเดิม เริ่ม–หยุดจับเวลาแบบเดียวกัน')+`<div class="table-wrap"><table><thead><tr><th>รอบ</th><th>เวลา (วินาที)</th><th>จำนวนของตก</th></tr></thead><tbody>${[0,1,2].map(i=>`<tr><td>${i+1}</td><td><input aria-label="เวลารอบ ${i+1}" type="number" min="0" step="0.1" data-lab-field="time${i}" value="${esc(s.values['time'+i]??'')}"></td><td><input aria-label="ของตกรอบ ${i+1}" type="number" min="0" step="1" data-lab-field="drop${i}" value="${esc(s.values['drop'+i]??'')}"></td></tr>`).join('')}</tbody></table></div><div id="model-result">${model(a,s).html}</div>`;
case 'fault_diagnosis':return `<div class="callout gold"><strong>ชุดข้อมูลตัวอย่างสมมติ</strong><p>รอบ 1 ของตก 2 ชิ้น · รอบ 2 ตก 1 ชิ้น · รอบ 3 ตก 2 ชิ้น สังเกตพบว่าช่องเก็บคับกว่าของที่ต้องหยิบ</p></div>`+field(s,'cause','คิดว่าสาเหตุคืออะไร มีหลักฐานใดสนับสนุน','เชื่อมสภาพช่องกับผลที่เกิด ไม่โทษคนหยิบโดยไม่มีข้อมูล')+field(s,'repair','เลือกแก้หนึ่งจุด และคาดว่าจะดีขึ้นอย่างไร','บอกสิ่งที่จะคงเดิมเพื่อทดสอบเปรียบเทียบ');
case 'revision_compare':return `<div class="table-wrap"><table><thead><tr><th>ตัวอย่างสมมติ</th><th>เวลา</th><th>พื้นที่ภายนอก</th></tr></thead><tbody><tr><td>รุ่นที่ 1</td><td>20 วินาที</td><td>18 × 12 ซม.</td></tr><tr><td>รุ่นที่ 2</td><td>12 วินาที</td><td>22 × 12 ซม.</td></tr></tbody></table></div><p class="mt">เกณฑ์: ไม่เกิน 15 วินาที และไม่เกินพื้นที่ 20×15 ซม.</p><div class="option-row">${['รุ่น 2 ผ่านทุกเกณฑ์','รุ่น 2 เร็วขึ้น แต่ยังเกินพื้นที่'].map(v=>`<button class="choice ${s.values.conclusion===v?'selected':''}" data-action="choice" data-key="conclusion" data-value="${v}">${v}</button>`).join('')}</div><div id="model-result">${model(a,s).html}</div>`;
case 'portfolio_story':return sequence(a,s)+field(s,'story','เขียนคำบรรยายเชื่อมหลักฐานของคุณ','ให้คนอ่านตามจากปัญหาไปถึงสิ่งที่เปลี่ยนและผลที่ยังไม่ผ่านได้');
default:return '<p>กำลังเตรียมกิจกรรมนี้</p>';
}}
function numeric(s,k){return s.values[k]!==''&&s.values[k]!=null&&Number.isFinite(+s.values[k])?+s.values[k]:null}
function model(a,s){let text='',warn=false;const v=s.values;switch(a.interaction){
case 'cause_chain':if(v.cause&&v.change&&v.effect){const ok=(v.cause.includes('พื้นที่น้อย')&&v.change.includes('ขนาดเล็ก')&&v.effect.startsWith('ใช้พื้นที่น้อย'))||(v.cause.includes('จำนวนมาก')&&v.change.includes('ขนาดใหญ่')&&v.effect.startsWith('ซักได้มาก'));text=ok?'สายเหตุผลสอดคล้องกับข้อมูลที่เลือก ลองเขียนข้อแลกเปลี่ยนด้วยคำของคุณ':'บางส่วนยังขัดกัน ลองตรวจว่าขนาดที่เลือกตอบข้อจำกัดอย่างไร';warn=!ok}break;
case 'constraint_switch':if(v.context&&v.method){warn=v.context.startsWith('ไฟดับ')&&!v.method.startsWith('ซักมือ');text=warn?'เครื่องซักผ้าใช้ไฟฟ้า แต่สถานการณ์นี้ไฟดับ ลองเปลี่ยนวิธีหรืออธิบายทรัพยากรสำรองที่มีจริง':'วิธีนี้นำไปพิจารณาต่อได้ ยังต้องอธิบายเรื่องเวลา แรง และข้อจำกัด ไม่ได้แปลว่าดีที่สุดทุกด้าน'}break;
case 'system_builder':{const n=[['input','sensor'],['process','controller'],['output','water'],['feedback','measure']].filter(([k,x])=>v[k]===x).length;text=`วางองค์ประกอบตรงหน้าที่ ${n}/4 ส่วน · ${n===4?'ข้อมูลย้อนกลับช่วยให้ปรับการทำงานรอบต่อไปได้':'อ่านหน้าที่แต่ละส่วน แล้วติดตามว่าน้ำและข้อมูลไปไหน'}`;warn=n<4;break}
case 'fault_injection':if(v.fault&&v.part){warn=(v.fault.startsWith('ดินชื้น')?v.part!=='ข้อมูลเข้าและการวัด':v.part!=='กระบวนการส่งน้ำ');text=warn?'ส่วนที่เลือกอาจไม่ใช่จุดเริ่มต้นที่ตรงอาการ ลองติดตามข้อมูลและการทำงานตั้งแต่ก่อนเกิดปัญหา':'จุดเริ่มตรวจสัมพันธ์กับอาการ แต่ยังต้องทดสอบเพื่อยืนยันสาเหตุ'}break;
case 'material_tradeoff':{const qa=numeric(s,'a')??0,qb=numeric(s,'b')??0,cost=qa*20+qb*50;warn=!Number.isInteger(qa)||!Number.isInteger(qb)||qa<0||qb<0||cost>60||qb<1;text=`งบรวม ${cost} / 60 บาท · ${warn?'ยังไม่ตรงข้อกำหนด ตรวจจำนวนชิ้น งบ และแผ่นฐานที่รับได้อย่างน้อย 0.5 กก.':'ตรงข้อจำกัดในข้อมูลจำลอง ยังต้องทดสอบชิ้นงานจริงแยกต่างหาก'}`;break}
case 'tool_plan':if(v.operation&&v.tool){warn=({'วัดขนาดกระดาษแข็ง':'ไม้บรรทัด','ตัดกระดาษแข็ง':'กรรไกรที่เหมาะกับวัสดุ','ยึดชิ้นกระดาษแข็ง':'เทปกาว'})[v.operation]!==v.tool;text=warn?'เครื่องมือกับหน้าที่ที่เลือกยังไม่ตรงกัน ลองพิจารณาว่าอยากวัด ตัด หรือยึด':'หน้าที่กับอุปกรณ์สอดคล้องกัน ระบุวิธีใช้และการดูแลความปลอดภัยก่อนทำจริง'}break;
case 'circuit_sim':text=`ผลแบบจำลอง: หลอดไฟ${v.connected&&v.switch?'ติด เพราะวงจรครบและสวิตช์ปิดวงจร':'ดับ '+(!v.connected?'เพราะสายยังไม่ครบวงจร':'เพราะสวิตช์เปิดวงจร')} · เปลี่ยนสวิตช์แล้ว ${s.toggles||0} ครั้ง`;break;
case 'mechanism_sim':{const r=+(v.radius||4),ax=+(v.axle||1);return {html:`<div class="wheel-demo"><div class="wheel" style="width:${50+r*9}px">ล้อ</div><div class="axle"></div><div class="wheel" style="width:${30+ax*18}px">เพลา</div></div><div class="feedback-note">รัศมีล้อ ${r} ซม. / เพลา ${ax} ซม. · อัตราส่วนรัศมี ${(r/ax).toFixed(1)} เท่า<br>ล้อหมุนหนึ่งรอบมีระยะรอบวง ${(2*Math.PI*r).toFixed(1)} ซม. เพลา ${(2*Math.PI*ax).toFixed(1)} ซม.<br>เป็นผลคำนวณจาก 2πr ไม่ใช่ผลวัดรถจริง</div>`,text:`radius=${r}; axle=${ax}; circumference=${2*Math.PI*r}`}}
case 'dimension_sketch':{const w=numeric(s,'width'),d=numeric(s,'depth');if(w!==null&&d!==null){warn=w<=0||d<=0||w>20||d>15;text=warn?'ขนาดภายนอกยังไม่ตรงพื้นที่ 20×15 ซม. ตรวจทั้งความกว้างและความลึก':'ขนาดภายนอกอยู่ในพื้นที่กำหนด แต่ยังต้องตรวจขนาดช่องและการเก็บไม้บรรทัดยาว 18 ซม.'}break}
case 'dependency_timeline':{const o=s.order;const valid=o.indexOf('กำหนดปัญหาและข้อจำกัด')<o.indexOf('วัดและร่างแบบ')&&o.indexOf('วัดและร่างแบบ')<o.indexOf('เลือกวัสดุและเตรียมชิ้นส่วน')&&o.indexOf('เลือกวัสดุและเตรียมชิ้นส่วน')<o.indexOf('ประกอบชิ้นส่วน')&&o.indexOf('ประกอบชิ้นส่วน')<o.indexOf('ทดสอบตามเกณฑ์')&&o.indexOf('ทดสอบตามเกณฑ์')<o.indexOf('ปรับปรุงจากผลทดสอบ');text=valid?'ลำดับพร้อมสำหรับวางเวลาทำงาน ยังย้อนกลับไปแก้แบบได้เมื่อพบปัญหา':'ตรวจงานที่ต้องรอกัน เช่น ต้องรู้ขนาดก่อนเตรียมชิ้นส่วน และต้องมีผลทดสอบก่อนสรุปสิ่งที่จะปรับ';warn=!valid;break}
case 'test_protocol':{if(!v.mode||v.mode==='ยังไม่ได้ทดลอง'){text='ยังไม่มีผลทดลอง ยอมรับสถานะนี้ได้ ไม่ต้องกรอกผลให้ดูผ่าน';break}const rows=[0,1,2].map(i=>{const t=numeric(s,'time'+i),d=numeric(s,'drop'+i);return t===null||d===null?'ยังไม่บันทึก':t<0||d<0||!Number.isInteger(d)?'ข้อมูลไม่ถูกต้อง':t<=15&&d===0?'ผ่านเกณฑ์รอบนี้':'ยังไม่ผ่านเกณฑ์รอบนี้'});text=`${v.mode}: ${rows.map((x,i)=>`รอบ ${i+1} ${x}`).join(' · ')}${v.mode==='ทดลองแบบจำลองดิจิทัล'?' · ไม่ใช้ยืนยันความแข็งแรงหรือทักษะเครื่องมือจริง':''}`;break}
case 'revision_compare':if(v.conclusion){warn=v.conclusion==='รุ่น 2 ผ่านทุกเกณฑ์';text=warn?'เวลาผ่านแล้ว แต่กว้าง 22 ซม. เกินพื้นที่ 20 ซม. ต้องตรวจทุกเกณฑ์ร่วมกัน':'ถูกต้อง รุ่นใหม่เร็วขึ้นแต่เกินพื้นที่ ควรลองปรับช่องภายในแทนการขยายฐาน'}break;
}return {text,html:text?`<div class="feedback-note ${warn?'warn':''}" role="status">${esc(text)}</div>`:''}}
function lab(c,id){if(window.DTLabs)return window.DTLabs.view(c,id);const list=chapLabs(c);currentLab=list.find(x=>x.id===id)||list[0];const a=currentLab,s=labState(a),l=D.lessons[a.moduleId];return `<div class="lab-layout"><aside class="lab-menu" aria-label="เลือกกิจกรรม">${list.map((x,i)=>`<button class="${x.id===a.id?'active':''}" data-action="lab" data-id="${x.id}" data-c="${c.number}"><span>${me().labs[x.id]?.savedAt?'✓':String(i+1).padStart(2,'0')}</span>${esc(x.title)}</button>`).join('')}</aside><section class="paper"><div class="lab-intro"><a class="tag" href="#chapter/${c.number}/learn/${a.moduleId}">กลับไปอ่านบทเรียนก่อนทำ</a><h2>${esc(a.title)}</h2><p>${esc(a.studentPrompt)}</p><p class="muted"><small>ข้อมูลตั้งต้น: ${esc(a.starterData)} · เวลาประมาณ ${a.estimateMinutes} นาที</small></p><ol class="lab-instructions">${a.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div><div class="lab-widget" id="lab-widget">${widget(a,s)}</div><label>อธิบายสิ่งที่ทำ ผลที่พบ และสิ่งที่อยากปรับ<textarea data-lab-reason maxlength="6000" placeholder="ครูจะอ่านเหตุผลของคุณ ไม่ได้ตรวจจากการเจอคำสำคัญเพียงคำเดียว">${esc(s.reason)}</textarea></label><div class="lab-actions"><div>${button('บันทึกกิจกรรมลงแฟ้ม','save-lab','','green')}${button('ดูแนวช่วยคิด','hint','','secondary')}</div><span class="status-text">${s.savedAt?'บันทึกกิจกรรม: '+fmt(s.savedAt):'ยังไม่บันทึกหลักฐานกิจกรรม'}</span></div><p class="inline-note mt">การบันทึกแสดงว่ามีหลักฐานให้ย้อนดู ไม่ได้แปลว่าผ่านการประเมิน ครูตรวจชิ้นงานและเหตุผลอีกครั้ง</p></section></div>`}

const workFields={1:[['observations','สำรวจสิ่งของและวิธีการรอบโต๊ะ','อย่างน้อย 3 รายการ พร้อมหน้าที่และปัญหาที่ช่วยแก้'],['problem','เลือกปัญหาหนึ่งเรื่องที่จะพัฒนาต่อ','ใครเจอปัญหา เกิดตอนไหน และสังเกตอะไรได้จริง'],['need','ความต้องการของผู้ใช้','เขียนสิ่งที่ต้องทำให้สำเร็จ โดยยังไม่ต้องระบุว่าจะซื้อหรือสร้างอะไร']],2:[['comparison','เปรียบเทียบวิธีจัดเก็บ 2 รูปแบบ','เช่น ลิ้นชักรวมกับถาดแบ่งช่อง ใช้ของชุดเดียวกันเป็นข้อมูล'],['causes','เหตุใดจึงเกิดการเปลี่ยนแปลง','เชื่อมความต้องการ วัสดุ หรือบริบทกับวิธีใหม่'],['tradeoff','แนวทางที่เลือกและข้อแลกเปลี่ยน','ข้อดี ข้อจำกัด และสิ่งที่เหมาะกับโต๊ะของตน']],3:[['system','อธิบายระบบเก็บ–หยิบ–คืนอุปกรณ์','แยกข้อมูลเข้า กระบวนการ ผลผลิต และข้อมูลย้อนกลับให้ชัด'],['cases','ทดลองหรือวิเคราะห์ 2 เงื่อนไข','เช่น เมื่อมีของครบกับมีของหาย ควรตรวจและตอบสนองอย่างไร'],['feedback','จะใช้ข้อมูลย้อนกลับแก้ปัญหาอย่างไร','บอกว่าตรวจอะไร เมื่อใด และนำไปปรับส่วนใด']],4:[['materials','ตารางเลือกวัสดุและงบประมาณ','ระบุจำนวน ราคา คุณสมบัติ และเหตุผลที่เหมาะกับหน้าที่'],['tools','เครื่องมือและลำดับการทำงาน','แต่ละเครื่องมือทำหน้าที่ใด และใช้เมื่อใด'],['safety','วิธีทำที่เหมาะสมและสิ่งที่ต้องให้ครูช่วย','แยกแผนจำลองออกจากการใช้เครื่องมือจริง']],5:[['mechanism','เลือกกลไกหรือวงจรที่จำเป็นกับงาน','อธิบายหน้าที่ ไม่เพิ่มไฟเพียงเพื่อให้สวย'],['states','อธิบายการทำงานอย่างน้อย 2 สถานะ','เช่น เปิด–ปิด หรือก่อน–หลังเคลื่อนที่'],['limits','ผลทดลองจำลองและข้อจำกัด','ระบุค่าที่เปลี่ยน สิ่งที่เกิด และสิ่งที่ยังยืนยันไม่ได้']],6:[['problem','ปัญหา ผู้ใช้ และเกณฑ์ความสำเร็จ','พื้นที่ 20×15 ซม. งบ 60 บาท และเป้าหมายหยิบของตามโจทย์'],['alternatives','แนวทาง 2 แบบและเหตุผลที่เลือก','เปรียบเทียบด้วยเกณฑ์เดียวกัน'],['design','แบบที่มีขนาดและวัสดุชัดเจน','เขียนขนาดช่องและตำแหน่ง หรืออ้างแบบร่างที่บันทึกในกิจกรรม'],['plan','แผนสร้างและแผนทดสอบ','ขั้นตอนที่ต้องรอกัน วัสดุ เครื่องมือ และวิธีเก็บผล']],7:[['prototype','ต้นแบบที่สร้างและสิ่งที่เปลี่ยนจากแผน','บอกว่าเป็นชิ้นงานจริงหรือแบบจำลอง พร้อมเหตุผลของการเปลี่ยน'],['tests','หลักฐานทดสอบอย่างน้อย 3 รอบ','ของ 4 ชิ้น เงื่อนไขเดิม เป้าหมายไม่ตกและไม่เกิน 15 วินาที อ้างตารางกิจกรรมได้'],['revision','ปรับอะไร เพราะหลักฐานใด','เก็บรุ่นก่อนและหลัง แยกผลสังเกตออกจากผลคาด'],['reflection','ข้อสรุป ข้อจำกัด และสิ่งที่จะทำต่อ','รายงานผลที่ยังไม่ผ่านได้ตรงไปตรงมา ไม่ใช้ภาพสวยแทนหลักฐาน']]};
/* คำถามแยกข้อจาก worksheet-data.js: ใช้คำถามหลักเป็นหัวข้อ และข้อย่อยเป็นคำใบ้ (คีย์เดิมคงไว้ งานร่างเก่าไม่หาย) */
const WG=window.DT_WORK_GUIDE;if(WG)Object.entries(workFields).forEach(([n,l])=>l.forEach(f=>{const g=WG.fields&&WG.fields[n]&&WG.fields[n][f[0]];if(g){f[1]=g.question;f[2]=g.prompts.join(' · ')}}));
function workQ(n,k,t,h){const g=WG&&WG.fields[n]&&WG.fields[n][k];if(!g)return `${t}<small>${h}</small>`;return `<span class="wq-q">${esc(g.question)}</span><ol class="wq-p">${g.prompts.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><small class="wq-ev"><b>ครูดูจาก:</b> ${esc(g.evidence)}</small><details class="wq-ex"><summary>ดูแนวเริ่มตอบและตัวอย่าง</summary><p><b>เริ่มตอบได้ว่า:</b> ${esc(g.starter)}</p><p><b>ตัวอย่างคนละงาน (ดูรูปแบบ ไม่ใช่คำตอบให้คัด):</b> ${esc(String(g.example).replace(/^ตัวอย่างคนละงาน:\s*/,''))}</p><p class="muted">เขียนเป็นข้อ ตาราง หรือผังก็ได้ ไม่ต้องใช้แนวเริ่มตอบก็ได้ ถ้ายังไม่ได้ทดลองให้เขียนตามจริงว่ายังไม่ได้ทดลอง</p></details>`}

