function arena(c){const e=D.encounters.find(x=>x.chapterId===c.id),b=D.bosses.find(x=>x.number===e.mainBoss);return `<section class="paper"><h2>${esc(e.arena)}</h2><p>${esc(e.planet)} · พบกับ <b>${esc(b.thaiName)}</b>${e.subBoss?' และบอสย่อย '+esc(D.bosses.find(x=>x.number===e.subBoss).thaiName):''}</p><div class="waiting-arena"><img class="arena-hero" src="assets/techno-sword.webp" alt="Techno ถือดาบ"><span>VS</span><img class="arena-boss" src="assets/boss-${b.number}.webp" alt="${esc(b.thaiName)}"></div><div class="grid2"><div class="card"><h3>แนวเกมที่วางไว้</h3><p>หลบสัญญาณโจมตีแล้วหาจังหวะสวน เล่นด้วย Z ฟัน, X หลบ, Space กระโดด และลูกศรเดิน มีโหมดช่วยและออกกลับบทเรียนได้</p></div><div class="card"><h3>รอบนี้เน้นทดสอบโครงบทเรียน</h3><p>ใช้ภาพตัวละครเดิมเพื่อดูขนาดพื้นที่ ยังไม่มีฉากใหม่หรือเกมที่แกล้งแสดงว่าทำเสร็จ คะแนนเกมในอนาคตจะแยกจากคะแนนชิ้นงาน</p></div></div><a class="btn green mt" href="#chapter/${c.number}/learn">กลับไปเรียนรู้</a></section>`}
