function redrawWidget(){if(!currentLab)return;const s=labState(currentLab),old=$('#lab-widget');old.innerHTML=widget(currentLab,s);if(currentLab.interaction==='dimension_sketch'){drawCleanup?.();setupSketch(s)}}
function updateModel(){if(currentLab&&$('#model-result'))$('#model-result').innerHTML=model(currentLab,labState(currentLab)).html}
function drawStrokes(canvas,strokes){const r=canvas.getBoundingClientRect(),ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,r.width*ratio);canvas.height=Math.max(1,r.height*ratio);const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);ctx.lineWidth=2.7;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#315d40';for(const line of strokes){if(!line.length)continue;ctx.beginPath();ctx.moveTo(line[0][0]*r.width,line[0][1]*r.height);for(const p of line.slice(1))ctx.lineTo(p[0]*r.width,p[1]*r.height);ctx.stroke()}}
function setupSketch(s){const canvas=$('#sketch');if(!canvas)return;let drawing=false;const coord=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]};canvas.addEventListener('pointerdown',e=>{drawing=true;canvas.setPointerCapture(e.pointerId);s.strokes.push([coord(e)]);drawStrokes(canvas,s.strokes)});canvas.addEventListener('pointermove',e=>{if(drawing&&s.strokes.at(-1).length<1500){s.strokes.at(-1).push(coord(e));drawStrokes(canvas,s.strokes)}});const end=()=>{if(drawing){drawing=false;scheduleSave()}};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);const resize=()=>drawStrokes(canvas,s.strokes);window.addEventListener('resize',resize);drawCleanup=()=>window.removeEventListener('resize',resize);resize()}

